\documentclass{article}
\usepackage[paperwidth=594mm,paperheight=841mm,margin=0mm]{geometry}
\usepackage{tcolorbox}
\tcbuselibrary{poster,skins,fitting}
\usepackage{graphicx}
\usepackage{amsmath,amssymb}
\usepackage{enumitem}
\usepackage[table]{xcolor}
\usepackage{lmodern}
\usepackage[T1]{fontenc}
\usepackage{tikz}
\usetikzlibrary{calc,patterns,positioning}
\pagestyle{empty}

% ═══════════════════════════════════════════════════════════════
% COOL-TONED COLOR SCHEME — Deep Navy / Teal / Bright Cyan
% ═══════════════════════════════════════════════════════════════
\definecolor{primary}{HTML}{0C4A6E}       % deep navy — title bar
\definecolor{secondary}{HTML}{0891B2}     % teal — section headers
\definecolor{accent}{HTML}{06B6D4}        % bright cyan — highlights
\definecolor{accentdeep}{HTML}{0E7490}    % deeper teal for variety
\definecolor{bgposter}{HTML}{EFF8FF}      % very light blue tint
\definecolor{cardbgA}{HTML}{F0F9FF}       % cool blue tint cards
\definecolor{cardbgB}{HTML}{ECFDF5}       % cool green tint cards
\definecolor{cardbgC}{HTML}{F5F3FF}       % cool lavender tint cards
\definecolor{titlebgA}{HTML}{DBEAFE}      % title bar tint A
\definecolor{titlebgB}{HTML}{CCFBF1}      % title bar tint B
\definecolor{titlebgC}{HTML}{E0E7FF}      % title bar tint C
\definecolor{textdark}{HTML}{0F172A}      % near-black text
\definecolor{textgray}{HTML}{475569}      % secondary text
\definecolor{stathighlight}{HTML}{DBEAFE} % stat box background
\definecolor{china}{HTML}{DC2626}         % China accent
\definecolor{india}{HTML}{EA580C}         % India accent
\definecolor{asiacolor}{HTML}{0891B2}     % Asia bar color
\definecolor{americascolor}{HTML}{059669} % Americas bar color
\definecolor{europecolor}{HTML}{7C3AED}   % Europe bar color
\definecolor{africacolor}{HTML}{D97706}   % Africa bar color

\pagecolor{bgposter}
\color{textdark}

% ═══════════════════════════════════════════════════════════════
% LIST STYLING
% ═══════════════════════════════════════════════════════════════
\setlist[itemize]{leftmargin=20pt, itemsep=8pt, parsep=2pt, topsep=2pt,
  label={\color{secondary}$\blacktriangleright$}}
\setlist[enumerate]{leftmargin=20pt, itemsep=8pt, parsep=2pt, topsep=2pt,
  label={\color{primary}\bfseries\arabic*.}}

% ═══════════════════════════════════════════════════════════════
% CARD STYLES — Left accent stripe design
% ═══════════════════════════════════════════════════════════════
\tcbset{
  tealcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=cardbgA,
    borderline west={5pt}{0pt}{secondary},
    left=14pt, right=12pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{32}{40}\selectfont\bfseries\color{secondary},
    coltitle=secondary, colbacktitle=titlebgA,
    toptitle=6pt, bottomtitle=6pt,
    titlerule=2pt, titlerule style={secondary!50},
    valign=top, drop shadow={opacity=0.15},
  },
  cyancard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=cardbgB,
    borderline west={5pt}{0pt}{accent},
    left=14pt, right=12pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{32}{40}\selectfont\bfseries\color{accentdeep},
    coltitle=accentdeep, colbacktitle=titlebgB,
    toptitle=6pt, bottomtitle=6pt,
    titlerule=2pt, titlerule style={accent!50},
    valign=top, drop shadow={opacity=0.15},
  },
  navycard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=cardbgC,
    borderline west={5pt}{0pt}{primary},
    left=14pt, right=12pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{32}{40}\selectfont\bfseries\color{primary},
    coltitle=primary, colbacktitle=titlebgC,
    toptitle=6pt, bottomtitle=6pt,
    titlerule=2pt, titlerule style={primary!50},
    valign=top, drop shadow={opacity=0.15},
  },
  highlightcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=primary!15!white,
    borderline west={6pt}{0pt}{primary},
    left=14pt, right=12pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{32}{40}\selectfont\bfseries\color{white},
    coltitle=white, colbacktitle=primary,
    toptitle=6pt, bottomtitle=6pt,
    valign=top, drop shadow={opacity=0.20},
  },
}

\begin{document}
\begin{tcbposter}[
  coverage={spread},
  poster={columns=2, rows=20, spacing=0mm},
]

% ══════════════════════════════════════════════════════════════
% TITLE BAR (span=2, top to row3)
% ══════════════════════════════════════════════════════════════
\posterbox[
  enhanced, colback=primary, colframe=primary, colupper=white,
  arc=0pt, boxrule=0pt,
  left=30pt, right=30pt, top=10pt, bottom=8pt,
  halign=center, valign=center,
  drop shadow={opacity=0.30}
]{name=title, column=1, span=2, between=top and row3}{
  {\fontsize{62}{74}\selectfont\bfseries Global Internet Usage}\\[8pt]
  {\fontsize{42}{52}\selectfont\bfseries\color{accent!70!white} A Cross-Country Comparison}\\[10pt]
  {\fontsize{22}{28}\selectfont\color{white!65} Internet Adoption, Digital Populations \& Economic Impact \textbar{} 2025 Data Report}
}

% ══════════════════════════════════════════════════════════════
% STATS BANNER (span=2, row3 to row5)
% ══════════════════════════════════════════════════════════════
\posterbox[
  enhanced, colback=primary!12!white, boxrule=0pt, arc=0pt,
  left=10pt, right=10pt, top=6pt, bottom=6pt,
  valign=center, borderline south={3pt}{0pt}{primary!30},
]{name=stats, column=1, span=2, between=row3 and row5}{
  \centering
  % Stat 1: Global Internet Users — LARGEST
  \begin{minipage}[c]{0.36\linewidth}\centering
    \fcolorbox{primary!30}{stathighlight}{\parbox{0.90\linewidth}{%
      \centering\vspace{6pt}%
      {\fontsize{60}{72}\selectfont\bfseries\color{primary} 5.56B}\\[4pt]
      {\fontsize{20}{26}\selectfont\color{textdark} Global Internet Users (2025)}\vspace{6pt}%
    }}
  \end{minipage}\hfill
  % Stat 2: Global Penetration
  \begin{minipage}[c]{0.28\linewidth}\centering
    \fcolorbox{secondary!25}{secondary!10!white}{\parbox{0.90\linewidth}{%
      \centering\vspace{6pt}%
      {\fontsize{50}{62}\selectfont\bfseries\color{accentdeep} 68\%}\\[4pt]
      {\fontsize{20}{26}\selectfont\color{textdark} Global Penetration Rate}\vspace{6pt}%
    }}
  \end{minipage}\hfill
  % Stat 3: E-Commerce
  \begin{minipage}[c]{0.28\linewidth}\centering
    \fcolorbox{accentdeep!25}{accentdeep!10!white}{\parbox{0.90\linewidth}{%
      \centering\vspace{6pt}%
      {\fontsize{50}{62}\selectfont\bfseries\color{primary} \$8.0T}\\[4pt]
      {\fontsize{20}{26}\selectfont\color{textdark} E-Commerce by 2027}\vspace{6pt}%
    }}
  \end{minipage}
}

% ══════════════════════════════════════════════════════════════
% LEFT COLUMN
% ══════════════════════════════════════════════════════════════

% ── Digital Population (row5 to row12) ──
\posterbox[navycard, title={The World's Digital Population}
]{name=digitalpop, column=1, between=row5 and row12}{
  \fontsize{22}{28}\selectfont

  % China + India callout
  \colorbox{primary!15}{\parbox{0.94\linewidth}{%
    \centering\vspace{4pt}%
    {\fontsize{20}{26}\selectfont\color{primary}\bfseries
    China \& India together represent ${\sim}$36\% of all global internet users}\\[2pt]
    {\fontsize{28}{34}\selectfont\bfseries
    \color{china} 1.09B \color{textdark}+\color{india} 900M
    \color{textgray}\fontsize{20}{26}\selectfont = nearly 2 billion online}\\[2pt]%
    \vspace{2pt}%
  }}

  \vspace{6pt}

  % Top 10 countries table with TikZ bars
  \begin{tikzpicture}[x=1mm, y=1mm]
    \fontsize{18}{22}\selectfont
    % Header
    \node[anchor=west, font=\fontsize{18}{22}\selectfont\bfseries\color{primary}]
      at (0, 0) {Country};
    \node[anchor=east, font=\fontsize{18}{22}\selectfont\bfseries\color{primary}]
      at (170, 0) {Online Pop.};
    \node[anchor=west, font=\fontsize{18}{22}\selectfont\bfseries\color{primary}]
      at (178, 0) {};

    \draw[primary!30, line width=0.5pt] (0, -3) -- (270, -3);

    % Row 1: China
    \node[anchor=west, font=\fontsize{17}{22}\selectfont\color{textdark}] at (0, -14) {China};
    \fill[china!80] (90, -18) rectangle (90 + 80, -10);
    \node[anchor=east, font=\fontsize{15}{20}\selectfont\bfseries\color{textdark}] at (88, -14) {1.09B};

    % Row 2: India
    \node[anchor=west, font=\fontsize{17}{22}\selectfont\color{textdark}] at (0, -30) {India};
    \fill[india!80] (90, -34) rectangle (90 + 66, -26);
    \node[anchor=east, font=\fontsize{15}{20}\selectfont\bfseries\color{textdark}] at (88, -30) {900M};

    % Row 3: United States
    \node[anchor=west, font=\fontsize{17}{22}\selectfont\color{textdark}] at (0, -46) {United States};
    \fill[americascolor!80] (90, -50) rectangle (90 + 24, -42);
    \node[anchor=east, font=\fontsize{15}{20}\selectfont\bfseries\color{textdark}] at (88, -46) {320M};

    % Row 4: Indonesia
    \node[anchor=west, font=\fontsize{17}{22}\selectfont\color{textdark}] at (0, -62) {Indonesia};
    \fill[asiacolor!80] (90, -66) rectangle (90 + 16, -58);
    \node[anchor=east, font=\fontsize{15}{20}\selectfont\bfseries\color{textdark}] at (88, -62) {220M};

    % Row 5: Brazil
    \node[anchor=west, font=\fontsize{17}{22}\selectfont\color{textdark}] at (0, -78) {Brazil};
    \fill[americascolor!80] (90, -82) rectangle (90 + 14, -74);
    \node[anchor=east, font=\fontsize{15}{20}\selectfont\bfseries\color{textdark}] at (88, -78) {190M};

    % Row 6: Japan
    \node[anchor=west, font=\fontsize{17}{22}\selectfont\color{textdark}] at (0, -94) {Japan};
    \fill[asiacolor!80] (90, -98) rectangle (90 + 9, -90);
    \node[anchor=east, font=\fontsize{15}{20}\selectfont\bfseries\color{textdark}] at (88, -94) {118M};

    % Row 7: Nigeria
    \node[anchor=west, font=\fontsize{17}{22}\selectfont\color{textdark}] at (0, -110) {Nigeria};
    \fill[africacolor!80] (90, -114) rectangle (90 + 8.5, -106);
    \node[anchor=east, font=\fontsize{15}{20}\selectfont\bfseries\color{textdark}] at (88, -110) {115M};

    % Row 8: Germany
    \node[anchor=west, font=\fontsize{17}{22}\selectfont\color{textdark}] at (0, -126) {Germany};
    \fill[europecolor!80] (90, -130) rectangle (90 + 6, -122);
    \node[anchor=east, font=\fontsize{15}{20}\selectfont\bfseries\color{textdark}] at (88, -126) {80M};

    % Row 9: United Kingdom
    \node[anchor=west, font=\fontsize{17}{22}\selectfont\color{textdark}] at (0, -142) {United Kingdom};
    \fill[europecolor!80] (90, -146) rectangle (90 + 5, -138);
    \node[anchor=east, font=\fontsize{15}{20}\selectfont\bfseries\color{textdark}] at (88, -142) {66M};

    % Row 10: South Korea
    \node[anchor=west, font=\fontsize{17}{22}\selectfont\color{textdark}] at (0, -158) {South Korea};
    \fill[asiacolor!80] (90, -162) rectangle (90 + 3.7, -154);
    \node[anchor=east, font=\fontsize{15}{20}\selectfont\bfseries\color{textdark}] at (88, -158) {50M};
  \end{tikzpicture}

  \vspace{2pt}
  {\fontsize{16}{20}\selectfont\color{textgray}\itshape
  Bar lengths proportional to online population. China \& India dwarf all others.}
}

% ── Key Takeaways (row12 to row16) ──
\posterbox[highlightcard, title={Key Takeaways}
]{name=takeaways, column=1, between=row12 and row16}{
  \fontsize{22}{30}\selectfont\color{textdark}
  \begin{enumerate}[itemsep=12pt]
    \item \textbf{Asia dominates} in absolute online population; Northern Europe and East Asia lead in penetration rates
    \item \textbf{Social media} usage grows steadily — average daily engagement nearing \textbf{2.5 hours}
    \item \textbf{Digital economy} expanding rapidly — e-commerce and AI are primary growth engines
    \item \textbf{Connectivity gaps} remain in Sub-Saharan Africa and South Asia — both challenge and opportunity
  \end{enumerate}
}

% ── Data & Sources (row16 to row20) ──
\posterbox[tealcard, title={Data \& Sources}
]{name=sources, column=1, between=row16 and row20}{
  \fontsize{20}{26}\selectfont\color{textdark}

  \colorbox{secondary!15}{\parbox{0.92\linewidth}{%
    \vspace{3pt}%
    {\fontsize{18}{24}\selectfont\color{accentdeep}\bfseries Global Internet Users (2025)}\\[2pt]
    {\fontsize{16}{22}\selectfont\color{textgray} ITU, Internet World Stats, DataReportal}
    \vspace{3pt}%
  }}

  \vspace{6pt}

  \colorbox{secondary!15}{\parbox{0.92\linewidth}{%
    \vspace{3pt}%
    {\fontsize{18}{24}\selectfont\color{accentdeep}\bfseries E-Commerce \& AI Projections}\\[2pt]
    {\fontsize{16}{22}\selectfont\color{textgray} Statista Digital Market Outlook, eMarketer}
    \vspace{3pt}%
  }}

  \vspace{6pt}

  \colorbox{secondary!15}{\parbox{0.92\linewidth}{%
    \vspace{3pt}%
    {\fontsize{18}{24}\selectfont\color{accentdeep}\bfseries Social Media \& Usage Data}\\[2pt]
    {\fontsize{16}{22}\selectfont\color{textgray} DataReportal, GlobalWebIndex, Meta Q4 2024}
    \vspace{3pt}%
  }}

  \vspace{6pt}

  {\fontsize{16}{20}\selectfont\color{textgray}\itshape
  Data reflects estimates as of early 2025. Figures rounded.}
}

% ══════════════════════════════════════════════════════════════
% RIGHT COLUMN
% ══════════════════════════════════════════════════════════════

% ── Penetration Rates (row5 to row14) — ANALYTICAL CENTERPIECE ──
\posterbox[tealcard, title={Internet Penetration Rates by Country}
]{name=penetration, column=2, between=row5 and row14}{
  \fontsize{20}{26}\selectfont

  \colorbox{secondary!18}{\parbox{0.92\linewidth}{%
    \vspace{3pt}%
    {\fontsize{18}{24}\selectfont\color{accentdeep}\bfseries
    Wide disparity: from 52\% in Nigeria to 98\% in South Korea}\\[1pt]
    {\fontsize{16}{20}\selectfont\color{textgray}
    Penetration = share of population with internet access}
    \vspace{3pt}%
  }}

  \vspace{8pt}

  % Horizontal bar chart — penetration rates
  \begin{tikzpicture}[x=1mm, y=1mm]
    % Scale: 100% = 140mm bar width
    \def\barwidth{140}

    % Column headers
    \node[anchor=east, font=\fontsize{16}{20}\selectfont\bfseries\color{primary}]
      at (72, 0) {};
    \node[anchor=west, font=\fontsize{14}{18}\selectfont\color{textgray}]
      at (75, 0) {0\%};
    \node[anchor=west, font=\fontsize{14}{18}\selectfont\color{textgray}]
      at (75 + 0.5*\barwidth, 0) {50\%};
    \node[anchor=east, font=\fontsize{14}{18}\selectfont\color{textgray}]
      at (75 + \barwidth, 0) {100\%};

    % Gridlines
    \draw[primary!15, line width=0.4pt] (75, -5) -- (75, -175);
    \draw[primary!15, line width=0.4pt, dashed] (75 + 0.5*\barwidth, -5) -- (75 + 0.5*\barwidth, -175);
    \draw[primary!15, line width=0.4pt] (75 + \barwidth, -5) -- (75 + \barwidth, -175);

    % Row 1: South Korea 98%
    \node[anchor=east, font=\fontsize{17}{22}\selectfont\color{textdark}] at (72, -14) {South Korea};
    \fill[asiacolor!85] (75, -18) rectangle (75 + 0.98*\barwidth, -10);
    \node[anchor=west, font=\fontsize{15}{20}\selectfont\bfseries\color{white}] at (75 + 0.98*\barwidth - 22, -14) {98\%};

    % Row 2: United Kingdom 97%
    \node[anchor=east, font=\fontsize{17}{22}\selectfont\color{textdark}] at (72, -30) {United Kingdom};
    \fill[europecolor!85] (75, -34) rectangle (75 + 0.97*\barwidth, -26);
    \node[anchor=west, font=\fontsize{15}{20}\selectfont\bfseries\color{white}] at (75 + 0.97*\barwidth - 22, -30) {97\%};

    % Row 3: Germany 96%
    \node[anchor=east, font=\fontsize{17}{22}\selectfont\color{textdark}] at (72, -46) {Germany};
    \fill[europecolor!85] (75, -50) rectangle (75 + 0.96*\barwidth, -42);
    \node[anchor=west, font=\fontsize{15}{20}\selectfont\bfseries\color{white}] at (75 + 0.96*\barwidth - 22, -46) {96\%};

    % Row 4: United States 95%
    \node[anchor=east, font=\fontsize{17}{22}\selectfont\color{textdark}] at (72, -62) {United States};
    \fill[americascolor!85] (75, -66) rectangle (75 + 0.95*\barwidth, -58);
    \node[anchor=west, font=\fontsize{15}{20}\selectfont\bfseries\color{white}] at (75 + 0.95*\barwidth - 22, -62) {95\%};

    % Row 5: Japan 95%
    \node[anchor=east, font=\fontsize{17}{22}\selectfont\color{textdark}] at (72, -78) {Japan};
    \fill[asiacolor!85] (75, -82) rectangle (75 + 0.95*\barwidth, -74);
    \node[anchor=west, font=\fontsize{15}{20}\selectfont\bfseries\color{white}] at (75 + 0.95*\barwidth - 22, -78) {95\%};

    % Row 6: Brazil 88%
    \node[anchor=east, font=\fontsize{17}{22}\selectfont\color{textdark}] at (72, -94) {Brazil};
    \fill[americascolor!85] (75, -98) rectangle (75 + 0.88*\barwidth, -90);
    \node[anchor=west, font=\fontsize{15}{20}\selectfont\bfseries\color{white}] at (75 + 0.88*\barwidth - 22, -94) {88\%};

    % Row 7: Indonesia 78%
    \node[anchor=east, font=\fontsize{17}{22}\selectfont\color{textdark}] at (72, -110) {Indonesia};
    \fill[asiacolor!85] (75, -114) rectangle (75 + 0.78*\barwidth, -106);
    \node[anchor=west, font=\fontsize{15}{20}\selectfont\bfseries\color{white}] at (75 + 0.78*\barwidth - 22, -110) {78\%};

    % Row 8: China 76%
    \node[anchor=east, font=\fontsize{17}{22}\selectfont\color{china}\bfseries] at (72, -126) {China};
    \fill[china!85] (75, -130) rectangle (75 + 0.76*\barwidth, -122);
    \node[anchor=west, font=\fontsize{15}{20}\selectfont\bfseries\color{white}] at (75 + 0.76*\barwidth - 22, -126) {76\%};

    % Row 9: India 62%
    \node[anchor=east, font=\fontsize{17}{22}\selectfont\color{india}\bfseries] at (72, -142) {India};
    \fill[india!85] (75, -146) rectangle (75 + 0.62*\barwidth, -138);
    \node[anchor=west, font=\fontsize{15}{20}\selectfont\bfseries\color{white}] at (75 + 0.62*\barwidth - 22, -142) {62\%};

    % Row 10: Nigeria 52%
    \node[anchor=east, font=\fontsize{17}{22}\selectfont\color{textdark}] at (72, -158) {Nigeria};
