[metadata] {"type": "text", "file": {"filePath": "/app/poster/main.tex", "content": "\\documentclass{article}\n\\usepackage[paperwidth=594mm,paperheight=841mm,margin=0mm]{geometry}\n\\usepackage{tcolorbox}\n\\tcbuselibrary{poster,skins,fitting}\n\\usepackage{graphicx}\n\\usepackage{amsmath,amssymb}\n\\usepackage{enumitem}\n\\usepackage[table]{xcolor}\n\\usepackage{lmodern}\n\\usepackage[T1]{fontenc}\n\\usepackage{tikz}\n\\usetikzlibrary{calc,patterns,positioning}\n\\pagestyle{empty}\n\n% ═══════════════════════════════════════════════════════════════\n% COOL-TONED COLOR SCHEME — Deep Navy / Teal / Bright Cyan\n% ═══════════════════════════════════════════════════════════════\n\\definecolor{primary}{HTML}{0C4A6E}       % deep navy\n\\definecolor{secondary}{HTML}{0891B2}     % teal\n\\definecolor{accent}{HTML}{06B6D4}        % bright cyan\n\\definecolor{accentdeep}{HTML}{0E7490}    % deeper teal\n\\definecolor{bgposter}{HTML}{EFF8FF}      % light blue tint\n\\definecolor{cardbgA}{HTML}{F0F9FF}       % cool blue tint\n\\definecolor{cardbgB}{HTML}{ECFDF5}       % cool green tint\n\\definecolor{cardbgC}{HTML}{F5F3FF}       % cool lavender tint\n\\definecolor{titlebgA}{HTML}{DBEAFE}\n\\definecolor{titlebgB}{HTML}{CCFBF1}\n\\definecolor{titlebgC}{HTML}{E0E7FF}\n\\definecolor{textdark}{HTML}{0F172A}\n\\definecolor{textgray}{HTML}{475569}\n\\definecolor{stathighlight}{HTML}{DBEAFE}\n\\definecolor{china}{HTML}{DC2626}\n\\definecolor{india}{HTML}{EA580C}\n\\definecolor{asiacolor}{HTML}{0891B2}\n\\definecolor{americascolor}{HTML}{059669}\n\\definecolor{europecolor}{HTML}{7C3AED}\n\\definecolor{africacolor}{HTML}{D97706}\n\n\\pagecolor{bgposter}\n\\color{textdark}\n\n% ═══════════════════════════════════════════════════════════════\n% LIST STYLING\n% ═══════════════════════════════════════════════════════════════\n\\setlist[itemize]{leftmargin=20pt, itemsep=8pt, parsep=2pt, topsep=2pt,\n  label={\\color{secondary}$\\blacktriangleright$}}\n\\setlist[enumerate]{leftmargin=20pt, it