Asia dominates} in absolute online population; Northern Europe and East Asia lead in penetration rates\n    \\item \\textbf{Social media} grows steadily --- average daily engagement nears \\textbf{2.5 hours}\n    \\item \\textbf{Digital economy} expands rapidly --- e-commerce and AI are primary growth engines\n    \\item \\textbf{Connectivity gaps} remain in Sub-Saharan Africa and South Asia --- both challenge and opportunity\n  \\end{enumerate}\n}\n\n% ── Data Sources (row16 to row20) ──\n\\posterbox[tealcard, title={Data \\& Sources}\n]{name=sources, column=1, between=row16 and row20}{\n  \\fontsize{18}{24}\\selectfont\\color{textdark}\n\n  \\colorbox{secondary!15}{\\parbox{0.92\\linewidth}{%\n    \\vspace{3pt}%\n    {\\fontsize{17}{22}\\selectfont\\color{accentdeep}\\bfseries Global Internet Users (2025)}\\\\[1pt]\n    {\\fontsize{15}{20}\\selectfont\\color{textgray} ITU, Internet World Stats, DataReportal}\n    \\vspace{3pt}%\n  }}\n\n  \\vspace{5pt}\n\n  \\colorbox{secondary!15}{\\parbox{0.92\\linewidth}{%\n    \\vspace{3pt}%\n    {\\fontsize{17}{22}\\selectfont\\color{accentdeep}\\bfseries E-Commerce \\& AI Projections}\\\\[1pt]\n    {\\fontsize{15}{20}\\selectfont\\color{textgray} Statista Digital Market Outlook, eMarketer}\n    \\vspace{3pt}%\n  }}\n\n  \\vspace{5pt}\n\n  \\colorbox{secondary!15}{\\parbox{0.92\\linewidth}{%\n    \\vspace{3pt}%\n    {\\fontsize{17}{22}\\selectfont\\color{accentdeep}\\bfseries Social Media \\& Usage Data}\\\\[1pt]\n    {\\fontsize{15}{20}\\selectfont\\color{textgray} DataReportal, GlobalWebIndex, Meta Q4 2024}\n    \\vspace{3pt}%\n  }}\n\n  \\vspace{5pt}\n\n  {\\fontsize{14}{18}\\selectfont\\color{textgray}\\itshape\n  Data reflects estimates as of early 2025. Figures rounded.}\n}\n\n% ══════════════════════════════════════════════════════════════\n% RIGHT COLUMN\n% ══════════════════════════════════════════════════════════════\n\n% ── Penetration Rates (row5 to row14) — CENTERPIECE ──\n\\posterbox[tealcard, title={Internet Penetration Rates by Country}\n]{name=penetration, column=2, between=row5 and row14}{\n  \\fontsize{20}{26}\\selectfont\n\n  \\colorbox{secondary!18}{\\parbox{0.92\\linewidth}{%\n    \\vspace{3pt}%\n    {\\fontsize{17}{22}\\selectfont\\color{accentdeep}\\bfseries\n    Wide disparity: from 52\\% in Nigeria to 98\\% in South Korea}\\\\[1pt]\n    {\\fontsize{14}{18}\\selectfont\\color{textgray}\n    Penetration = share of population with internet access}\n    \\vspace{3pt}%\n  }}\n\n  \\vspace{8pt}\n\n  % Horizontal bar chart\n  \\begin{tikzpicture}[x=1mm, y=1mm]\n    \\def\\barwidth{155}\n\n    % Scale markers\n    \\node[anchor=west, font=\\fontsize{13}{16}\\selectfont\\color{textgray}]\n      at (78, 0) {0\\%};\n    \\node[anchor=west, font=\\fontsize{13}{16}\\selectfont\\color{textgray}]\n      at (78 + 0.5*\\barwidth - 6, 0) {50\\%};\n    \\node[anchor=east, font=\\fontsize{13}{16}\\selectfont\\color{textgray}]\n      at (78 + \\barwidth + 2, 0) {100\\%};\n\n    % Gridlines\n    \\draw[primary!12, line width=0.4pt] (78, -6) -- (78, -176);\n    \\draw[primary!12, line width=0.4pt, dashed] (78 + 0.5*\\barwidth, -6) -- (78 + 0.5*\\barwidth, -176);\n    \\draw[primary!12, line width=0.4pt] (78 + \\barwidth, -6) -- (78 + \\barwidth, -176);\n\n    % Row 1: South Korea 98%\n    \\node[anchor=east, font=\\fontsize{18}{22}\\selectfont\\color{textdark}] at (74, -15) {South Korea};\n    \\fill[asiacolor!90] (78, -20) rectangle (78 + 0.98*\\barwidth, -10);\n    \\node[anchor=east, font=\\fontsize{16}{20}\\selectfont\\bfseries\\color{white}] at (78 + 0.98*\\barwidth - 3, -15) {98\\%};\n\n    % Row 2: United Kingdom 97%\n    \\node[anchor=east, font=\\fontsize{18}{22}\\selectfont\\color{textdark}] at (74, -33) {United Kingdom};\n    \\fill[europecolor!90] (78, -38) rectangle (78 + 0.97*\\barwidth, -28);\n    \\node[anchor=east, font=\\fontsize{16}{20}\\selectfont\\bfseries\\color{white}] at (78 + 0.97*\\barwidth - 3, -33) {97\\%};\n\n    % Row 3: Germany 96%\n    \\node[anchor=east, font=\\fontsize{18}{22}\\selectfont\\color{textdark}] at (74, -51) {Germany};\n    \\fill[europecolor!90] (78, -56) rectangle (78 + 0.96*\\barwidth, -46);\n    \\node[anchor=east, font=\\fontsize{16}{20}\\selectfont\\bfseries\\color{white}] at (78 + 0.96*\\barwidth - 3, -51) {96\\%};\n\n    % Row 4: United States 95%\n    \\node[anchor=east, font=\\fontsize{18}{22}\\selectfont\\color{textdark}] at (74, -69) {United States};\n    \\fill[americascolor!90] (78, -74) rectangle (78 + 0.95*\\barwidth, -64);\n    \\node[anchor=east, font=\\fontsize{16}{20}\\selectfont\\bfseries\\color{white}] at (78 + 0.95*\\barwidth - 3, -69) {95\\%};\n\n    % Row 5: Japan 95%\n    \\node[anchor=east, font=\\fontsize{18}{22}\\selectfont\\color{textdark}] at (74, -87) {Japan};\n    \\fill[asiacolor!90] (78, -92) rectangle (78 + 0.95*\\barwidth, -82);\n    \\node[anchor=east, font=\\fontsize{16}{20}\\selectfont\\bfseries\\color{white}] at (78 + 0.95*\\barwidth - 3, -87) {95\\%};\n\n    % Row 6: Brazil 88%\n    \\node[anchor=east, font=\\fontsize{18}{22}\\selectfont\\color{textdark}] at (74, -105) {Brazil};\n    \\fill[americascolor!90] (78, -110) rectangle (78 + 0.88*\\barwidth, -100);\n    \\node[anchor=east, font=\\fontsize{16}{20}\\selectfont\\bfseries\\color{white}] at (78 + 0.88*\\barwidth - 3, -105) {88\\%};\n\n    % Row 7: Indonesia 78%\n    \\node[anchor=east, font=\\fontsize{18}{22}\\selectfont\\color{textdark}] at (74, -123) {Indonesia};\n    \\fill[asiacolor!90] (78, -128) rectangle (78 + 0.78*\\barwidth, -118);\n    \\node[anchor=east, font=\\fontsize{16}{20}\\selectfont\\bfseries\\color{white}] at (78 + 0.78*\\barwidth - 3, -123) {78\\%};\n\n    % Row 8: China 76% — highlighted\n    \\node[anchor=east, font=\\fontsize{18}{22}\\selectfont\\bfseries\\color{china}] at (74, -141) {China};\n    \\fill[china!90] (78, -146) rectangle (78 + 0.76*\\barwidth, -136);\n    \\node[anchor=east, font=\\fontsize{16}{20}\\selectfont\\bfseries\\color{white}] at (78 + 0.76*\\barwidth - 3, -141) {76\\%};\n\n    % Row 9: India 62% — highlighted\n    \\node[anchor=east, font=\\fontsize{18}{22}\\selectfont\\bfseries\\color{india}] at (74, -159) {India};\n    \\fill[india!90] (78, -164) rectangle (78 + 0.62*\\barwidth, -154);\n    \\node[anchor=east, font=\\fontsize{16}{20}\\selectfont\\bfseries\\color{white}] at (78 + 0.62*\\barwidth - 3, -159) {62\\%};\n\n    % Row 10: Nigeria 52%\n    \\node[anchor=east, font=\\fontsize{18}{22}\\selectfont\\color{textdark}] at (74, -177) {Nigeria};\n    \\fill[africacolor!90] (78, -182) rectangle (78 + 0.52*\\barwidth, -172);\n    \\node[anchor=east, font=\\fontsize{16}{20}\\selectfont\\bfseries\\color{white}] at (78 + 0.52*\\barwidth - 3, -177) {52\\%};\n\n    % Region legend at bottom\n    \\draw[primary!15, line width=0.3pt] (78, -190) -- (78 + \\barwidth, -190);\n\n    \\fill[asiacolor!80] (80, -198) rectangle (92, -192);\n    \\node[anchor=west, font=\\fontsize{12}{16}\\selectfont\\color{textgray}] at (96, -195) {Asia};\n\n    \\fill[europecolor!80] (130, -198) rectangle (142, -192);\n    \\node[anchor=west, font=\\fontsize{12}{16}\\selectfont\\color{textgray}] at (146, -195) {Europe};\n\n    \\fill[americascolor!80] (185, -198) rectangle (197, -192);\n    \\node[anchor=west, font=\\fontsize{12}{16}\\selectfont\\color{textgray}] at (201, -195) {Americas};\n\n    \\fill[africacolor!80] (245, -198) rectangle (257, -192);\n    \\node[anchor=west, font=\\fontsize{12}{16}\\selectfont\\color{textgray}] at (261, -195) {Africa};\n  \\end{tikzpicture}\n}\n\n% ── Usage Trends (row14 to row17) ──\n\\posterbox[cyancard, title={How People Spend Time Online}\n]{name=usage, column=2, between=row14 and row17}{\n  \\fontsize{20}{26}\\selectfont\\color{textdark}\n\n  % Daily usage stat\n  \\colorbox{accent!18}{\\parbox{0.92\\linewidth}{%\n    \\vspace{4pt}%\n    \\centering\n    {\\fontsize{40}{48}\\selectfont\\bfseries\\color{accentdeep} 143 min/day}\\\\[2pt]\n    {\\fontsize{17}{22}\\selectfont\\color{textdark} Average Global Social Media Usage (2025)}\n    \\vspace{4pt}%\n  }}\n\n  \\vspace{8pt}\n\n  % Platform bars\n  {\\fontsize{17}{22}\\selectfont\\color{primary}\\bfseries Top Platforms by Monthly Active Users}\n\n  \\vspace{4pt}\n\n  \\begin{tikzpicture}[x=1mm, y=1mm]\n    \\def\\platwidth{120}\n\n    % Facebook 3.1B\n    \\node[anchor=east, font=\\fontsize{15}{20}\\selectfont\\color{textdark}] at (56, 0) {Facebook};\n    \\fill[primary!80] (60, -4) rectangle (60 + 3.1/3.1*\\platwidth, 4);\n    \\node[anchor=west, font=\\fontsize{14}{18}\\selectfont\\bfseries\\color{white}] at (60 + 3.1/3.1*\\platwidth - 24, 0) {3.1B};\n\n    % YouTube 2.5B\n    \\node[anchor=east, font=\\fontsize{15}{20}\\selectfont\\color{textdark}] at (56, -18) {YouTube};\n    \\fill[secondary!80] (60, -22) rectangle (60 + 2.5/3.1*\\platwidth, -14);\n    \\node[anchor=west, font=\\fontsize{14}{18}\\selectfont\\bfseries\\color{white}] at (60 + 2.5/3.1*\\platwidth - 24, -18) {2.5B};\n\n    % WhatsApp 2.4B\n    \\node[anchor=east, font=\\fontsize{15}{20}\\selectfont\\color{textdark}] at (56, -36) {WhatsApp};\n    \\fill[accent!80] (60, -40) rectangle (60 + 2.4/3.1*\\platwidth, -32);\n    \\node[anchor=west, font=\\fontsize{14}{18}\\selectfont\\bfseries\\color{white}] at (60 + 2.4/3.1*\\platwidth - 24, -36) {2.4B};\n\n    % Instagram 2.0B\n    \\node[anchor=east, font=\\fontsize{15}{20}\\selectfont\\color{textdark}] at (56, -54) {Instagram};\n    \\fill[europecolor!80] (60, -58) rectangle (60 + 2.0/3.1*\\platwidth, -50);\n    \\node[anchor=west, font=\\fontsize{14}{18}\\selectfont\\bfseries\\color{white}] at (60 + 2.0/3.1*\\platwidth - 24, -54) {2.0B};\n\n    % TikTok 1.6B\n    \\node[anchor=east, font=\\fontsize{15}{20}\\selectfont\\color{textdark}] at (56, -72) {TikTok};\n    \\fill[africacolor!80] (60, -76) rectangle (60 + 1.6/3.1*\\platwidth, -68);\n    \\node[anchor=west, font=\\fontsize{14}{18}\\selectfont\\bfseries\\color{white}] at (60 + 1.6/3.1*\\platwidth - 24, -72) {1.6B};\n  \\end{tikzpicture}\n}\n\n% ── Digital Economy (row17 to row20) ──\n\\posterbox[navycard, title={The Digital Economy Impact}\n]{name=economy, column=2, between=row17 and row20}{\n  \\fontsize{20}{26}\\selectfont\\color{textdark}\n\n  % E-commerce growth callout — POWERFUL CLOSING\n  \\colorbox{primary!20}{\\parbox{0.92\\linewidth}{%\n    \\vspace{5pt}%\n    \\centering\n    {\\fontsize{38}{46}\\selectfont\\bfseries\\color{primary} \\$6.3T $\\to$ \\$8.0T}\\\\[3pt]\n    {\\fontsize{16}{22}\\selectfont\\color{textdark} Global Retail E-Commerce (2024 $\\to$ 2027 est.)}\n    \\vspace{5pt}%\n  }}\n\n  \\vspace{6pt}\n\n  % AI market\n  \\colorbox{accent!20}{\\parbox{0.92\\linewidth}{%\n    \\vspace{5pt}%\n    \\centering\n    {\\fontsize{30}{38}\\selectfont\\bfseries\\color{accentdeep} \\$240B $\\to$ \\$800B+}\\\\[2pt]\n    {\\fontsize{16}{22}\\selectfont\\color{textdark} AI Market Forecast (2023 $\\to$ 2030)}\n    \\vspace{5pt}%\n  }}\n\n  \\vspace{6pt}\n\n  \\begin{itemize}[itemsep=6pt, leftmargin=18pt]\n    \\item {\\fontsize{17}{22}\\selectfont E-commerce exceeds \\textbf{20\\%} of total retail globally}\n    \\item {\\fontsize{17}{22}\\selectfont Mobile: \\textbf{60\\%+} of all web traffic worldwide}\n    \\item {\\fontsize{17}{22}\\selectfont \\textbf{180+ zettabytes} of data created by 2025}\n  \\end{itemize}\n}\n\n\\end{tcbposter}\n\\end{document}\n", "numLines": 498, "startLine": 1, "totalLines": 498}}

