\documentclass{article}
\usepackage[paperwidth=594mm,paperheight=841mm,margin=0mm]{geometry}
\usepackage{tcolorbox}
\tcbuselibrary{poster,skins,fitting}
\usepackage{graphicx}
\usepackage{amsmath,amssymb}
\usepackage{enumitem}
\usepackage[table]{xcolor}
\usepackage{lmodern}
\usepackage[T1]{fontenc}
\usepackage{tikz}
\usetikzlibrary{calc,patterns,positioning}
\pagestyle{empty}

% ═══════════════════════════════════════════════════════════════
% COOL-TONED COLOR SCHEME — Deep Navy / Teal / Bright Cyan
% ═══════════════════════════════════════════════════════════════
\definecolor{primary}{HTML}{0C4A6E}       % deep navy
\definecolor{secondary}{HTML}{0891B2}     % teal
\definecolor{accent}{HTML}{06B6D4}        % bright cyan
\definecolor{accentdeep}{HTML}{0E7490}    % deeper teal
\definecolor{bgposter}{HTML}{EFF8FF}      % light blue tint
\definecolor{cardbgA}{HTML}{F0F9FF}       % cool blue tint
\definecolor{cardbgB}{HTML}{ECFDF5}       % cool green tint
\definecolor{cardbgC}{HTML}{F5F3FF}       % cool lavender tint
\definecolor{titlebgA}{HTML}{DBEAFE}
\definecolor{titlebgB}{HTML}{CCFBF1}
\definecolor{titlebgC}{HTML}{E0E7FF}
\definecolor{textdark}{HTML}{0F172A}
\definecolor{textgray}{HTML}{475569}
\definecolor{stathighlight}{HTML}{DBEAFE}
\definecolor{china}{HTML}{DC2626}
\definecolor{india}{HTML}{EA580C}
\definecolor{asiacolor}{HTML}{0891B2}
\definecolor{americascolor}{HTML}{059669}
\definecolor{europecolor}{HTML}{7C3AED}
\definecolor{africacolor}{HTML}{D97706}

\pagecolor{bgposter}
\color{textdark}

% ═══════════════════════════════════════════════════════════════
% LIST STYLING
% ═══════════════════════════════════════════════════════════════
\setlist[itemize]{leftmargin=20pt, itemsep=8pt, parsep=2pt, topsep=2pt,
  label={\color{secondary}$\blacktriangleright$}}
\setlist[enumerate]{leftmargin=20pt, itemsep=10pt, parsep=2pt, topsep=2pt,
  label={\color{primary}\bfseries\arabic*.}}

% ═══════════════════════════════════════════════════════════════
% CARD STYLES
% ═══════════════════════════════════════════════════════════════
\tcbset{
  tealcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=cardbgA,
    borderline west={5pt}{0pt}{secondary},
    left=14pt, right=12pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{30}{38}\selectfont\bfseries\color{secondary},
    coltitle=secondary, colbacktitle=titlebgA,
    toptitle=6pt, bottomtitle=6pt,
    titlerule=2pt, titlerule style={secondary!50},
    valign=top, drop shadow={opacity=0.15},
  },
  cyancard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=cardbgB,
    borderline west={5pt}{0pt}{accent},
    left=14pt, right=12pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{30}{38}\selectfont\bfseries\color{accentdeep},
    coltitle=accentdeep, colbacktitle=titlebgB,
    toptitle=6pt, bottomtitle=6pt,
    titlerule=2pt, titlerule style={accent!50},
    valign=top, drop shadow={opacity=0.15},
  },
  navycard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=cardbgC,
    borderline west={5pt}{0pt}{primary},
    left=14pt, right=12pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{30}{38}\selectfont\bfseries\color{primary},
    coltitle=primary, colbacktitle=titlebgC,
    toptitle=6pt, bottomtitle=6pt,
    titlerule=2pt, titlerule style={primary!50},
    valign=top, drop shadow={opacity=0.15},
  },
  highlightcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=primary!15!white,
    borderline west={6pt}{0pt}{primary},
    left=14pt, right=12pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{30}{38}\selectfont\bfseries\color{white},
    coltitle=white, colbacktitle=primary,
    toptitle=6pt, bottomtitle=6pt,
    valign=top, drop shadow={opacity=0.20},
  },
}

\begin{document}
\begin{tcbposter}[
  coverage={spread},
  poster={columns=2, rows=20, spacing=0mm},
]

% ══════════════════════════════════════════════════════════════
% TITLE BAR (span=2, top to row3)
% ══════════════════════════════════════════════════════════════
\posterbox[
  enhanced, colback=primary, colframe=primary, colupper=white,
  arc=0pt, boxrule=0pt,
  left=30pt, right=30pt, top=10pt, bottom=8pt,
  halign=center, valign=center,
  drop shadow={opacity=0.30}
]{name=title, column=1, span=2, between=top and row3}{
  % Subtle globe dots decoration
  \begin{tikzpicture}[overlay, remember picture]
    \foreach \i in {1,...,30}{
      \pgfmathsetmacro{\xp}{rand*280+5}
      \pgfmathsetmacro{\yp}{rand*25+5}
      \fill[white, opacity=0.06] (\xp, \yp) circle (1.5pt);
    }
  \end{tikzpicture}
  {\fontsize{62}{74}\selectfont\bfseries Global Internet Usage}\\[8pt]
  {\fontsize{40}{50}\selectfont\bfseries\color{accent!70!white} A Cross-Country Comparison}\\[10pt]
  {\fontsize{20}{26}\selectfont\color{white!65} Internet Adoption, Digital Populations \& Economic Impact \textbar{} 2025}
}

% ══════════════════════════════════════════════════════════════
% STATS BANNER (span=2, row3 to row5) — 5.56B DOMINANT
% ══════════════════════════════════════════════════════════════
\posterbox[
  enhanced, colback=primary!12!white, boxrule=0pt, arc=0pt,
  left=10pt, right=10pt, top=6pt, bottom=6pt,
  valign=center, borderline south={3pt}{0pt}{primary!30},
]{name=stats, column=1, span=2, between=row3 and row5}{
  \centering
  % Stat 1: Global Internet Users — VISUALLY DOMINANT
  \begin{minipage}[c]{0.40\linewidth}\centering
    \fcolorbox{primary!40}{primary!8!white}{\parbox{0.92\linewidth}{%
      \centering\vspace{8pt}%
      {\fontsize{72}{86}\selectfont\bfseries\color{primary} 5.56B}\\[6pt]
      {\fontsize{20}{26}\selectfont\color{textdark} Global Internet Users (2025)}\vspace{8pt}%
    }}
  \end{minipage}\hfill
  % Stat 2: Penetration
  \begin{minipage}[c]{0.26\linewidth}\centering
    \fcolorbox{secondary!30}{secondary!8!white}{\parbox{0.90\linewidth}{%
      \centering\vspace{6pt}%
      {\fontsize{52}{64}\selectfont\bfseries\color{accentdeep} 68\%}\\[4pt]
      {\fontsize{18}{24}\selectfont\color{textdark} Global Penetration Rate}\vspace{6pt}%
    }}
  \end{minipage}\hfill
  % Stat 3: E-Commerce
  \begin{minipage}[c]{0.26\linewidth}\centering
    \fcolorbox{accentdeep!30}{accentdeep!8!white}{\parbox{0.90\linewidth}{%
      \centering\vspace{6pt}%
      {\fontsize{52}{64}\selectfont\bfseries\color{primary} \$8.0T}\\[4pt]
      {\fontsize{18}{24}\selectfont\color{textdark} E-Commerce by 2027}\vspace{6pt}%
    }}
  \end{minipage}
}

% ══════════════════════════════════════════════════════════════
% LEFT COLUMN
% ══════════════════════════════════════════════════════════════

% ── Digital Population (row5 to row12) ──
\posterbox[navycard, title={The World's Digital Population}
]{name=digitalpop, column=1, between=row5 and row12}{
  \fontsize{22}{28}\selectfont

  % China + India HERO callout — side by side boxes
  \begin{minipage}[t]{0.48\linewidth}
    \fcolorbox{china!40}{china!10!white}{\parbox{0.88\linewidth}{%
      \centering\vspace{6pt}%
      {\fontsize{36}{44}\selectfont\bfseries\color{china} 1.09B}\\[2pt]
      {\fontsize{18}{24}\selectfont\color{textdark} China}\\[1pt]
      {\fontsize{14}{18}\selectfont\color{textgray} 76\% penetration}%
      \vspace{4pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[t]{0.48\linewidth}
    \fcolorbox{india!40}{india!10!white}{\parbox{0.88\linewidth}{%
      \centering\vspace{6pt}%
      {\fontsize{36}{44}\selectfont\bfseries\color{india} 900M}\\[2pt]
      {\fontsize{18}{24}\selectfont\color{textdark} India}\\[1pt]
      {\fontsize{14}{18}\selectfont\color{textgray} 62\% penetration}%
      \vspace{4pt}%
    }}
  \end{minipage}

  \vspace{4pt}
  \centerline{%
    {\fontsize{16}{20}\selectfont\color{primary}\bfseries
    Together: ${\sim}$36\% of all global internet users}%
  }

  \vspace{6pt}

  % Top 10 countries — population bars (wider bars)
  \begin{tikzpicture}[x=1mm, y=1mm]
    \fontsize{16}{20}\selectfont
    % Header
    \node[anchor=west, font=\fontsize{16}{20}\selectfont\bfseries\color{primary}]
      at (0, 0) {Country};
    \node[anchor=west, font=\fontsize{16}{20}\selectfont\bfseries\color{primary}]
      at (68, 0) {Online Population};

    \draw[primary!25, line width=0.5pt] (0, -4) -- (260, -4);

    % Row 1: China
    \node[anchor=west, font=\fontsize{16}{20}\selectfont\bfseries\color{china}] at (0, -14) {China};
    \fill[china!75] (68, -18) rectangle (68 + 109, -10);
    \node[anchor=west, font=\fontsize{14}{18}\selectfont\bfseries\color{white}] at (68 + 109 - 26, -14) {1.09B};

    % Row 2: India
    \node[anchor=west, font=\fontsize{16}{20}\selectfont\bfseries\color{india}] at (0, -30) {India};
    \fill[india!75] (68, -34) rectangle (68 + 90, -26);
    \node[anchor=west, font=\fontsize{14}{18}\selectfont\bfseries\color{white}] at (68 + 90 - 24, -30) {900M};

    % Row 3: United States
    \node[anchor=west, font=\fontsize{16}{20}\selectfont\color{textdark}] at (0, -46) {United States};
    \fill[americascolor!75] (68, -50) rectangle (68 + 32, -42);
    \node[anchor=west, font=\fontsize{14}{18}\selectfont\bfseries\color{textdark}] at (68 + 34, -46) {320M};

    % Row 4: Indonesia
    \node[anchor=west, font=\fontsize{16}{20}\selectfont\color{textdark}] at (0, -62) {Indonesia};
    \fill[asiacolor!75] (68, -66) rectangle (68 + 22, -58);
    \node[anchor=west, font=\fontsize{14}{18}\selectfont\bfseries\color{textdark}] at (68 + 24, -62) {220M};

    % Row 5: Brazil
    \node[anchor=west, font=\fontsize{16}{20}\selectfont\color{textdark}] at (0, -78) {Brazil};
